import {LESSONS,LEVELS,CATEGORIES,CATEGORY_NAMES,BLOCK_LIBRARY,LESSON_UNITS} from '../data/seed.js';
import {cloud} from './cloud-service.js';
const $=s=>document.querySelector(s),app=$('#adminApp');
const K={users:'sar.users.v3',lessons:'sar.lessons.v3',levels:'sar.levels.v3',events:'sar.events.v3',settings:'sar.settings.v3',announcements:'sar.announcements.v5',maintenance:'sar.maintenance.v5',contacts:'sar.contacts.v5',audio:'sar.audio.v58'};
const DEFAULT_THEME={primary:'#6c5ce7',accent:'#ffb703',panelOpacity:.76,cardOpacity:.90,blur:8,radius:30,scale:1,theme:'pastel'};
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
if(!localStorage.getItem(K.lessons))set(K.lessons,LESSONS);if(!localStorage.getItem(K.levels))set(K.levels,LEVELS);
if(!localStorage.getItem('sar.v33.migrated')){localStorage.setItem('sar.backup.pre-v33',JSON.stringify({lessons:get(K.lessons,[]),levels:get(K.levels,[]),at:new Date().toISOString()}));set(K.lessons,LESSONS);set(K.levels,LEVELS);localStorage.setItem('sar.v33.migrated','1')}if(!localStorage.getItem(K.settings))set(K.settings,DEFAULT_THEME);
let auth=sessionStorage.getItem('sar.admin.auth')==='1',active='dash',fail=0,lastTry=0;
const esc=(s='')=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const cleanUrl=v=>String(v||'').trim();
function youtubeEmbed(url){try{const u=new URL(url,location.href);let id='';if(u.hostname.includes('youtu.be'))id=u.pathname.split('/').filter(Boolean)[0]||'';else if(u.hostname.includes('youtube.com')){if(u.pathname==='/watch')id=u.searchParams.get('v')||'';else if(u.pathname.startsWith('/shorts/'))id=u.pathname.split('/')[2]||'';else if(u.pathname.startsWith('/embed/'))id=u.pathname.split('/')[2]||'';}return id?`https://www.youtube.com/embed/${encodeURIComponent(id)}`:''}catch{return ''}}
function driveDirect(url,kind='file'){try{const u=new URL(url,location.href);if(!u.hostname.includes('drive.google.com'))return url;const m=u.pathname.match(/\/file\/d\/([^/]+)/);const id=m?.[1]||u.searchParams.get('id');if(!id)return url;return kind==='image'?`https://drive.google.com/uc?export=view&id=${encodeURIComponent(id)}`:`https://drive.google.com/uc?export=download&id=${encodeURIComponent(id)}`;}catch{return url}}
function normalizeLessonMedia(l={}){const items=Array.isArray(l.mediaItems)?l.mediaItems.map(x=>({type:['image','video','audio','link'].includes(x?.type)?x.type:'link',url:cleanUrl(x?.url),caption:String(x?.caption||'').trim()})).filter(x=>x.url):[];if(items.length)return items;return [['image',l.imageUrl],['video',l.videoUrl],['audio',l.audioUrl]].filter(([,u])=>cleanUrl(u)).map(([type,url])=>({type,url:cleanUrl(url),caption:''}))}
function mediaPreviewItemsHtml(items=[]){items=(items||[]).filter(x=>cleanUrl(x?.url));return `<div class="media-admin-preview"><h3>👀 ตัวอย่างสื่อ (${items.length})</h3><div class="media-preview-grid">${items.map((m,i)=>{const u=cleanUrl(m.url),cap=esc(m.caption||''),yt=m.type==='video'?youtubeEmbed(u):'';if(m.type==='image')return `<div class="media-preview-card"><b>🖼️ รูปภาพ ${i+1}</b><img src="${esc(driveDirect(u,'image'))}" alt="${cap||'ตัวอย่างรูป'}" onerror="this.style.display='none';this.nextElementSibling.hidden=false"><small hidden>⚠️ เปิดรูปไม่ได้ ตรวจสอบสิทธิ์หรือ URL</small>${cap?`<small>${cap}</small>`:''}</div>`;if(m.type==='video')return `<div class="media-preview-card"><b>🎬 วิดีโอ ${i+1}</b>${yt?`<iframe src="${esc(yt)}" title="Video preview" allowfullscreen></iframe>`:`<video controls playsinline preload="metadata" src="${esc(driveDirect(u,'file'))}"></video>`}${cap?`<small>${cap}</small>`:''}</div>`;if(m.type==='audio')return `<div class="media-preview-card"><b>🔊 เสียง ${i+1}</b><audio controls preload="metadata" src="${esc(driveDirect(u,'file'))}"></audio>${cap?`<small>${cap}</small>`:''}</div>`;return `<div class="media-preview-card"><b>🔗 ลิงก์ ${i+1}</b><a class="secondary" href="${esc(u)}" target="_blank" rel="noopener noreferrer">เปิดลิงก์</a>${cap?`<small>${cap}</small>`:''}</div>`}).join('')||'<small>ยังไม่ได้เพิ่มสื่อ</small>'}</div></div>`}
function jumpToEditor(selector){requestAnimationFrame(()=>requestAnimationFrame(()=>{const el=document.querySelector(selector);if(!el)return;el.scrollIntoView({behavior:'smooth',block:'start'});const input=el.querySelector('input:not([disabled]), textarea, select');setTimeout(()=>input?.focus({preventScroll:true}),350)}))}

async function hydrateCloud(){if(!cloud.enabled)return;try{const [players,shared]=await Promise.all([cloud.listPlayers(),cloud.loadShared()]);set(K.users,players);if(shared.content?.lessons)set(K.lessons,shared.content.lessons);if(shared.content?.levels)set(K.levels,shared.content.levels);if(shared.settings)set(K.settings,shared.settings)}catch(e){console.error(e)}}
const syncContent=()=>cloud.saveShared({lessons:get(K.lessons,[]),levels:get(K.levels,[])}).catch(console.error);
const syncSettings=()=>cloud.saveShared({settings:get(K.settings,{})}).catch(console.error);
function login(){app.innerHTML=`<section class="admin-login"><div class="admin-login-card"><div class="hero"><div style="font-size:4rem">🛡️</div><h1>Scratch AR Admin Studio</h1><p>จัดการระบบโดยไม่เปิดกล้องและไม่ตรวจจับมือ</p></div><label>ชื่อผู้ใช้<input id="u" autocomplete="username"></label><label>รหัสผ่าน<input id="p" type="password" autocomplete="current-password"></label><input id="site" hidden><button id="go" class="primary" style="width:100%">เข้าสู่ระบบ</button><p id="msg"></p><div class="actions"><a class="secondary" href="./index.html">← กลับหน้าเกม</a></div></div></section>`;$('#go').onclick=async()=>{const now=Date.now();if(now-lastTry<900)return;lastTry=now;if($('#site').value)return;$('#go').disabled=true;try{let ok=false;if(cloud.enabled){await cloud.adminLogin($('#u').value.trim(),$('#p').value);ok=true}else ok=$('#u').value==='Krukriangsak'&&$('#p').value==='22112547';if(!ok)throw new Error('ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง');sessionStorage.setItem('sar.admin.auth','1');auth=true;await hydrateCloud();dashboard()}catch(e){fail++;$('#msg').textContent=fail>=5?'ตรวจพบความพยายามผิดปกติ กรุณารอ 30 วินาที':(e.message||'เข้าสู่ระบบไม่สำเร็จ');if(fail>=5)setTimeout(()=>{fail=0;$('#go')&&($('#go').disabled=false)},30000)}finally{if(fail<5&&$('#go'))$('#go').disabled=false}}}
function layout(){app.innerHTML=`<div class="admin-layout"><aside class="admin-sidebar"><div class="admin-brand">🐱 <span>Scratch AR Studio</span></div><nav class="admin-nav">${[['dash','📊','ภาพรวม'],['users','👥','ผู้เล่น'],['lessons','📚','บทเรียน'],['levels','🗺️','ด่านและการเชื่อมโยง'],['blocks','🧩','คลังบล็อก'],['studio','🎮','สร้างด่านแบบลากบล็อก'],['gamebuilder','🕹️','Game Builder'],['announcements','📢','ประกาศ'],['system','🛠️','ปิดปรับปรุง'],['contacts','💬','ช่องทางติดต่อ'],['audio','🎵','ระบบเสียง'],['theme','🎨','ปรับแต่ง UI'],['logs','🛡️','บันทึกและบอท'],['backup','💾','สำรองข้อมูล']].map(([id,ic,n])=>`<button data-tab="${id}" class="${id===active?'active':''}">${ic} <span>${n}</span></button>`).join('')}</nav></aside><main class="admin-main"><header class="admin-topbar"><div><h1 id="pageTitle">ผู้ดูแลระบบ</h1><small>แก้ไขเนื้อหา ด่าน คะแนน และหน้าตาระบบได้จากที่เดียว</small></div><div class="actions" style="margin:0"><a class="secondary" href="./index.html">ดูหน้าเกม</a><button id="out" class="danger">ออกจากระบบ</button></div></header><section id="content" class="admin-content"></section></main></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{active=b.dataset.tab;layout();tab(active)});$('#out').onclick=async()=>{sessionStorage.removeItem('sar.admin.auth');await cloud.signOut();auth=false;login()}}
function dashboard(){layout();tab('dash')}
function tab(t){const c=$('#content'),title={dash:'ภาพรวมระบบ',users:'จัดการผู้เล่น',lessons:'จัดการบทเรียน',levels:'ด่านและการเชื่อมโยง',blocks:'คลังบล็อก Scratch',studio:'Scratch Level Studio',announcements:'ระบบประกาศ',system:'ปิดระบบเพื่อปรับปรุง',contacts:'ช่องทางติดต่อผู้ดูแล',audio:'เสียงกดและเพลงพื้นหลัง',theme:'ปรับแต่ง UI และธีม',logs:'บันทึกกิจกรรมและบอท',gamebuilder:'Game Creator Studio',backup:'สำรองและกู้คืนข้อมูล'}[t];$('#pageTitle').textContent=title;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));if(t==='dash')dash(c);if(t==='users')usersTab(c);if(t==='lessons')lessonsTab(c);if(t==='levels')levelsTab(c);if(t==='blocks')blocksTab(c);if(t==='studio')studioTab(c);if(t==='gamebuilder')gameBuilderTab(c);if(t==='announcements')announcementsTab(c);if(t==='system')systemTab(c);if(t==='contacts')contactsTab(c);if(t==='audio')audioTab(c);if(t==='theme')themeTab(c);if(t==='logs')logsTab(c);if(t==='backup')backupTab(c)}
function dash(c){const us=get(K.users,[]),ls=get(K.lessons,LESSONS),lv=get(K.levels,LEVELS),ev=get(K.events,[]);c.innerHTML=`<div class="admin-grid"><div class="admin-stat"><b>${us.length}</b>ผู้เล่นทั้งหมด</div><div class="admin-stat"><b>${ls.length}</b>บทเรียน</div><div class="admin-stat"><b>${lv.length}</b>ด่าน</div><div class="admin-stat"><b>${ev.filter(e=>e.type==='bot_flag').length}</b>Bot Flags</div></div><div class="editor-card"><h3>ทางลัด</h3><div class="actions" style="justify-content:flex-start"><button class="primary" data-jump="lessons">เพิ่ม/แก้บทเรียน</button><button class="secondary" data-jump="levels">ตั้งค่าการปลดล็อกด่าน</button><button class="secondary" data-jump="theme">ปรับสีและความโปร่งใส</button><button class="secondary" data-jump="audio">ตั้งค่าเสียงและเพลง</button></div></div>`;document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{active=b.dataset.jump;layout();tab(active)})}
function usersTab(c){
 const draw=()=>{
  const us=get(K.users,[]),now=Date.now(),onlineWindow=(window.SAR_CLOUD_OPTIONS?.onlineWindowSeconds||120)*1000;
  const isOnline=u=>u.online!==false&&u.lastSeen&&(now-new Date(u.lastSeen).getTime()<onlineWindow);
  c.innerHTML=`<div class="admin-section-head"><div><h2>👥 ฐานข้อมูลผู้เล่นออนไลน์</h2><p>ข้อมูลจากทุกเครื่องจะรวมอยู่ใน Firebase เดียวกันและอัปเดตแบบเรียลไทม์</p></div><button id="newPlayer" class="primary">+ สร้างผู้ใช้</button></div>
  <div class="admin-grid"><div class="admin-stat"><b>${us.length}</b>ผู้เล่นทั้งหมด</div><div class="admin-stat"><b>${us.filter(isOnline).length}</b>ออนไลน์</div><div class="admin-stat"><b>${us.filter(u=>u.status==='disabled').length}</b>ถูกระงับ</div><div class="admin-stat"><b>${new Set(us.map(u=>u.classroom).filter(Boolean)).size}</b>ห้องเรียน</div></div>
  <div class="editor-card"><label>ค้นหาผู้เล่น<input id="playerSearch" placeholder="ชื่อหรือห้องเรียน"></label></div>
  <div id="playerTable" style="overflow:auto"></div><div id="playerDrawer"></div>`;
  const renderTable=()=>{const q=($('#playerSearch')?.value||'').trim().toLowerCase(),arr=us.filter(u=>!q||`${u.name} ${u.classroom}`.toLowerCase().includes(q));$('#playerTable').innerHTML=`<table class="admin-table"><tr><th>สถานะ</th><th>ผู้เล่น</th><th>ชั้น</th><th>คะแนน</th><th>ดาว</th><th>เข้าใช้ล่าสุด</th><th>จัดการ</th></tr>${arr.map(u=>`<tr><td>${isOnline(u)?'🟢 ออนไลน์':'⚪ ออฟไลน์'}</td><td>${u.avatar||'🐱'} ${esc(u.name)}</td><td>${esc(u.classroom||'-')}</td><td>${u.score||0}</td><td>${u.stars||0}</td><td>${u.lastSeen?new Date(u.lastSeen).toLocaleString('th-TH'):'-'}</td><td><button class="secondary" data-edit-user="${u.id}">แก้ไข</button> <button class="${u.status==='disabled'?'primary':'danger'}" data-status-user="${u.id}">${u.status==='disabled'?'เปิดใช้':'ระงับ'}</button></td></tr>`).join('')||'<tr><td colspan="7">ยังไม่มีผู้เล่น</td></tr>'}</table>`;
   document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>openEditor(b.dataset.editUser));
   document.querySelectorAll('[data-status-user]').forEach(b=>b.onclick=async()=>{const u=us.find(x=>x.id===b.dataset.statusUser);if(!u)return;u.status=u.status==='disabled'?'active':'disabled';await cloud.setPlayerStatus(u.id,u.status);set(K.users,us);draw()});
  };
  $('#playerSearch').oninput=renderTable;renderTable();
  const openEditor=id=>{const u=us.find(x=>x.id===id);if(!u)return;$('#playerDrawer').innerHTML=`<div class="editor-drawer"><div class="editor-head"><h2>แก้ไขผู้เล่น: ${esc(u.name)}</h2><button id="closeUser" class="secondary">✕ ปิด</button></div><div class="admin-grid"><label>ชื่อผู้เล่น<input id="euName" value="${esc(u.name)}" disabled></label><label>ชั้นเรียน<input id="euClass" value="${esc(u.classroom||'')}"></label><label>อวตาร<input id="euAvatar" value="${esc(u.avatar||'🐱')}"></label><label>คะแนน<input id="euScore" type="number" value="${u.score||0}"></label><label>ดาว<input id="euStars" type="number" value="${u.stars||0}"></label></div><p><small>ชื่อและ PIN เชื่อมกับ Firebase Authentication จึงไม่เปลี่ยนจากตารางนี้ เพื่อป้องกันบัญชีเข้าไม่ได้</small></p><div class="actions"><button id="saveUserOne" class="primary">บันทึก</button><button id="deleteUserDoc" class="danger">ลบข้อมูลผู้เล่น</button></div></div>`;$('#closeUser').onclick=()=>$('#playerDrawer').innerHTML='';$('#saveUserOne').onclick=async()=>{u.classroom=$('#euClass').value.trim();u.avatar=$('#euAvatar').value.trim()||'🐱';u.score=Number($('#euScore').value||0);u.stars=Number($('#euStars').value||0);await cloud.updatePlayerAsAdmin(u);set(K.users,us);draw()};$('#deleteUserDoc').onclick=async()=>{if(!confirm('ยืนยันลบข้อมูลผู้เล่น? บัญชี Authentication อาจยังคงอยู่'))return;await cloud.deletePlayer(u);set(K.users,us.filter(x=>x.id!==u.id));draw()};jumpToEditor('#playerDrawer .editor-drawer')};
  $('#newPlayer').onclick=()=>{$('#playerDrawer').innerHTML=`<div class="editor-drawer"><div class="editor-head"><h2>สร้างผู้ใช้ใหม่ในฐานข้อมูลออนไลน์</h2><button id="closeNewUser" class="secondary">✕ ปิด</button></div><div class="admin-grid"><label>ชื่อผู้เล่น<input id="nuName" maxlength="20"></label><label>ชั้นเรียน<input id="nuClass" placeholder="ป.4/1"></label><label>PIN 4 หลัก<input id="nuPin" inputmode="numeric" maxlength="4"></label><label>อวตาร<input id="nuAvatar" value="🐱"></label></div><button id="createUserNow" class="primary">สร้างบัญชีออนไลน์</button><p id="createUserMsg"></p></div>`;$('#closeNewUser').onclick=()=>$('#playerDrawer').innerHTML='';$('#createUserNow').onclick=async()=>{const btn=$('#createUserNow');btn.disabled=true;try{await cloud.createPlayerAsAdmin({name:$('#nuName').value.trim(),classroom:$('#nuClass').value.trim(),avatar:$('#nuAvatar').value.trim()},$('#nuPin').value.trim());$('#createUserMsg').textContent='สร้างผู้ใช้สำเร็จ';setTimeout(()=>{},300)}catch(e){console.error(e);$('#createUserMsg').textContent=e.code==='auth/email-already-in-use'?'ชื่อนี้ถูกใช้แล้ว':(e.message||'สร้างไม่สำเร็จ')}finally{btn.disabled=false}};jumpToEditor('#playerDrawer .editor-drawer')};
 };
 draw();
 if(cloud.enabled)cloud.subscribeToPlayers(players=>{set(K.users,players);if(active==='users')draw()});
}

function lessonsTab(c){
 const ls=get(K.lessons,LESSONS); c.innerHTML=`<div class="admin-section-head"><div><h2>📚 จัดการบทเรียน</h2><p>กด “แก้ไข” เพื่อเปิดแบบฟอร์มเฉพาะบทเรียนนั้น และเพิ่มสื่อได้หลายรายการโดยไม่กำหนดจำนวนตายตัว</p></div><button id="addL" class="primary">+ เพิ่มบทเรียน</button></div><div class="manager-list">${ls.map(l=>`<article class="manager-row"><div class="manager-icon">${LESSON_UNITS[l.unit||'commands']?.icon||'📘'}</div><div><b>${esc(l.title)}</b><small>${l.id} • ${LESSON_UNITS[l.unit||'commands']?.title||'หมวดคำสั่ง'} • ${CATEGORY_NAMES[l.category]||l.category} • สื่อ ${normalizeLessonMedia(l).length} รายการ</small></div><span class="tag">${l.published!==false?'เผยแพร่':'ซ่อน'}</span><button class="secondary" data-edit-l="${l.id}">แก้ไข</button></article>`).join('')}</div><div id="lessonDrawer"></div>`;
 const open=id=>{const l=get(K.lessons,LESSONS).find(x=>x.id===id); if(!l)return;let media=normalizeLessonMedia(l);
  const mediaRows=()=>media.map((m,i)=>`<div class="editor-card lesson-media-row" data-media-i="${i}" style="margin:10px 0;padding:14px"><div class="admin-grid"><label>ประเภท<select data-media-type="${i}"><option value="image" ${m.type==='image'?'selected':''}>🖼️ รูปภาพ</option><option value="video" ${m.type==='video'?'selected':''}>🎬 วิดีโอ</option><option value="audio" ${m.type==='audio'?'selected':''}>🔊 เสียง</option><option value="link" ${m.type==='link'?'selected':''}>🔗 ลิงก์ทั่วไป</option></select></label><label>URL<input type="url" data-media-url="${i}" placeholder="https://..." value="${esc(m.url||'')}"></label><label>คำบรรยาย (ไม่บังคับ)<input data-media-caption="${i}" placeholder="เช่น ภาพตัวอย่างขั้นตอนที่ 1" value="${esc(m.caption||'')}"></label><div style="display:flex;align-items:end"><button type="button" class="danger" data-remove-media="${i}">🗑️ ลบรายการ</button></div></div></div>`).join('');
  const renderMediaEditor=()=>{const host=$('#lessonMediaRows');if(!host)return;host.innerHTML=mediaRows();host.querySelectorAll('[data-remove-media]').forEach(b=>b.onclick=()=>{pullMedia();media.splice(Number(b.dataset.removeMedia),1);renderMediaEditor();refreshPreview()});host.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{pullMedia();refreshPreview()}))};
  const pullMedia=()=>{media=media.map((m,i)=>({type:document.querySelector(`[data-media-type="${i}"]`)?.value||m.type,url:cleanUrl(document.querySelector(`[data-media-url="${i}"]`)?.value??m.url),caption:String((document.querySelector(`[data-media-caption="${i}"]`)?.value ?? m.caption) || '').trim()}))};
  $('#lessonDrawer').innerHTML=`<div class="editor-drawer" data-editor-id="${esc(l.id)}"><div class="editor-head"><h2>แก้ไข: ${esc(l.title)}</h2><button id="closeEditor" class="secondary">✕ ปิด</button></div><div class="admin-grid"><label>รหัส<input id="lid" value="${esc(l.id)}" disabled></label><label>ชื่อบทเรียน<input id="ltitle" value="${esc(l.title)}"></label><label>หมวดใหญ่<select id="lunit">${Object.entries(LESSON_UNITS).map(([k,v])=>`<option value="${k}" ${k===(l.unit||'commands')?'selected':''}>${v.icon} ${v.title}</option>`).join('')}</select></label><label>หมวดบล็อก<select id="lcat">${Object.keys(CATEGORIES).map(x=>`<option value="${x}" ${x===l.category?'selected':''}>${CATEGORY_NAMES[x]}</option>`).join('')}</select></label><label>คะแนนครั้งเดียว<input id="lpoints" type="number" value="${l.points||0}"></label><label><span>สถานะ</span><span><input id="lpub" type="checkbox" ${l.published!==false?'checked':''}> เผยแพร่</span></label></div><label>เนื้อหา<textarea id="lcontent">${esc(l.content||'')}</textarea></label><label>บล็อกภาษาอังกฤษ บรรทัดละ 1 บล็อก<textarea id="lblocks">${esc((l.blocks||[]).join('\n'))}</textarea></label><div class="editor-card"><div class="admin-section-head"><div><h3>🖼️🎬🔊🔗 สื่อประกอบบทเรียน</h3><p>เพิ่มรูป วิดีโอ เสียง หรือลิงก์ได้หลายรายการ กด + เพื่อเพิ่มแถวใหม่</p></div><div class="actions"><button id="addImageMedia" class="secondary" type="button">+ รูป</button><button id="addVideoMedia" class="secondary" type="button">+ วิดีโอ</button><button id="addAudioMedia" class="secondary" type="button">+ เสียง</button><button id="addLinkMedia" class="secondary" type="button">+ ลิงก์</button></div></div><div id="lessonMediaRows"></div></div><div id="lessonMediaPreview">${mediaPreviewItemsHtml(media)}</div><div class="actions"><button id="previewLessonMedia" class="secondary">👀 ทดสอบสื่อทั้งหมด</button><button id="saveOneLesson" class="primary">💾 บันทึกบทเรียนนี้</button><button id="deleteOneLesson" class="danger">ลบบทเรียน</button></div></div>`;
  const refreshPreview=()=>{pullMedia();$('#lessonMediaPreview').innerHTML=mediaPreviewItemsHtml(media)};
  const addMedia=type=>{pullMedia();media.push({type,url:'',caption:''});renderMediaEditor();const i=media.length-1;document.querySelector(`[data-media-url="${i}"]`)?.focus();jumpToEditor(`[data-media-i="${i}"]`)};
  $('#closeEditor').onclick=()=>$('#lessonDrawer').innerHTML='';
  renderMediaEditor();
  $('#addImageMedia').onclick=()=>addMedia('image');$('#addVideoMedia').onclick=()=>addMedia('video');$('#addAudioMedia').onclick=()=>addMedia('audio');$('#addLinkMedia').onclick=()=>addMedia('link');
  $('#previewLessonMedia').onclick=refreshPreview;
  $('#saveOneLesson').onclick=()=>{pullMedia();const all=get(K.lessons,LESSONS),i=all.findIndex(x=>x.id===id);const cleanMedia=media.filter(x=>cleanUrl(x.url)).map(x=>({...x,url:cleanUrl(x.url)}));all[i]={...l,title:$('#ltitle').value,unit:$('#lunit').value,category:$('#lcat').value,points:Number($('#lpoints').value),published:$('#lpub').checked,content:$('#lcontent').value,blocks:$('#lblocks').value.split('\n').map(x=>x.trim()).filter(Boolean),mediaItems:cleanMedia,imageUrl:'',videoUrl:'',audioUrl:''};set(K.lessons,all);syncContent();lessonsTab(c);setTimeout(()=>{document.querySelector(`[data-edit-l="${CSS.escape(id)}"]`)?.click()},0)};
  $('#deleteOneLesson').onclick=()=>{if(confirm('ยืนยันลบบทเรียนนี้?')){set(K.lessons,get(K.lessons,LESSONS).filter(x=>x.id!==id));syncContent();lessonsTab(c)}};
  jumpToEditor('#lessonDrawer .editor-drawer')};
 document.querySelectorAll('[data-edit-l]').forEach(b=>b.onclick=()=>open(b.dataset.editL)); $('#addL').onclick=()=>{const all=get(K.lessons,LESSONS),id='L'+Date.now();all.push({id,title:'บทเรียนใหม่',unit:'commands',category:'motion',points:50,content:'',blocks:[],mediaItems:[],published:true});set(K.lessons,all);syncContent();lessonsTab(c);setTimeout(()=>document.querySelector(`[data-edit-l="${id}"]`)?.click(),0)}
}
function levelsTab(c){
 const lv=get(K.levels,LEVELS),ls=get(K.lessons,LESSONS); c.innerHTML=`<div class="admin-section-head"><div><h2>🗺️ จัดการด่าน</h2><p>เลือกชื่อด่านจากรายการ แล้วค่อยเปิดแบบฟอร์มแก้ไขเฉพาะด่านนั้น</p></div><button id="addV" class="primary">+ เพิ่มด่าน</button></div><div class="manager-list">${lv.sort((a,b)=>a.order-b.order).map(v=>`<article class="manager-row"><div class="manager-icon">${v.published!==false?'🔓':'🔒'}</div><div><b>ด่าน ${v.order}: ${esc(v.title)}</b><small>${v.id} • เชื่อม ${v.lessonIds?.length||0} บทเรียน • ครั้งแรก ${v.firstScore||0} คะแนน</small></div><span class="tag">${v.published!==false?'เผยแพร่':'ซ่อน'}</span><button class="secondary" data-edit-v="${v.id}">แก้ไข</button></article>`).join('')}</div><div id="levelDrawer"></div>`;
 const open=id=>{const all=get(K.levels,LEVELS),v=all.find(x=>x.id===id);if(!v)return;$('#levelDrawer').innerHTML=`<div class="editor-drawer"><div class="editor-head"><h2>แก้ไขด่าน ${v.order}: ${esc(v.title)}</h2><button id="closeV" class="secondary">✕ ปิด</button></div><div class="admin-grid"><label>ลำดับ<input id="vorder" type="number" value="${v.order}"></label><label>ชื่อด่าน<input id="vtitle" value="${esc(v.title)}"></label><label>คะแนนครั้งแรก<input id="vfirst" type="number" value="${v.firstScore||300}"></label><label>คะแนนเล่นซ้ำ<input id="vrepeat" type="number" value="${v.repeatScore||100}"></label><label>บทเรียนที่ต้องเรียน<select id="vlessons" multiple size="8">${ls.map(l=>`<option value="${l.id}" ${(v.lessonIds||[]).includes(l.id)?'selected':''}>${l.id} — ${l.title}</option>`).join('')}</select></label><label>ด่านก่อนหน้า<select id="vprevious"><option value="">ไม่กำหนด</option>${all.filter(x=>x.id!==v.id).map(x=>`<option value="${x.id}" ${v.previousLevelId===x.id?'selected':''}>${x.id} — ${x.title}</option>`).join('')}</select></label></div><label>ลำดับคำตอบบล็อก<textarea id="vanswer" rows="9">${esc((v.answer||[]).join('\n'))}</textarea></label><label><input id="vpub" type="checkbox" ${v.published!==false?'checked':''}> เผยแพร่</label><div class="actions"><button id="saveOneLevel" class="primary">💾 บันทึกด่านนี้</button><button id="deleteOneLevel" class="danger">ลบด่าน</button></div></div>`;$('#closeV').onclick=()=>$('#levelDrawer').innerHTML='';$('#saveOneLevel').onclick=()=>{const arr=get(K.levels,LEVELS),i=arr.findIndex(x=>x.id===id);arr[i]={...v,order:Number($('#vorder').value),title:$('#vtitle').value,firstScore:Number($('#vfirst').value),repeatScore:Number($('#vrepeat').value),lessonIds:[...$('#vlessons').selectedOptions].map(o=>o.value),previousLevelId:$('#vprevious').value||null,answer:$('#vanswer').value.split('\n').map(x=>x.trim()).filter(Boolean),published:$('#vpub').checked};set(K.levels,arr);syncContent();levelsTab(c);setTimeout(()=>document.querySelector(`[data-edit-v="${CSS.escape(id)}"]`)?.click(),0)};$('#deleteOneLevel').onclick=()=>{if(confirm('ยืนยันลบด่านนี้?')){set(K.levels,get(K.levels,LEVELS).filter(x=>x.id!==id));syncContent();levelsTab(c)}};jumpToEditor('#levelDrawer .editor-drawer')};
 document.querySelectorAll('[data-edit-v]').forEach(b=>b.onclick=()=>open(b.dataset.editV));$('#addV').onclick=()=>{const all=get(K.levels,LEVELS),id='LV'+Date.now();all.push({id,order:all.length+1,title:'ด่านใหม่',lessonIds:[],previousLevelId:null,answer:[],firstScore:300,repeatScore:100,maxStars:3,published:true});set(K.levels,all);syncContent();levelsTab(c);setTimeout(()=>document.querySelector(`[data-edit-v="${id}"]`)?.click(),0)}
}
function blocksTab(c){c.innerHTML=`<p>คลังบล็อกอ้างอิงที่ใช้ในบทเรียนและด่าน แบ่งสีและรูปทรงตามประเภทของ Scratch</p>${Object.keys(CATEGORIES).map(cat=>`<section class="editor-card"><h3><span style="color:${CATEGORIES[cat]}">●</span> ${CATEGORY_NAMES[cat]}</h3><div class="palette">${BLOCK_LIBRARY.filter(b=>b.category===cat).map(b=>`<div><div class="block shape-${b.shape}" style="--c:${CATEGORIES[cat]}">${esc(b.text)}</div><small>${esc(b.meaning||'')}</small></div>`).join('')}</div></section>`).join('')}`}
function studioTab(c){
  const all=get(K.levels,LEVELS),ls=get(K.lessons,LESSONS);let answer=[],distractors=[];
  const block=(b,kind)=>`<div class="block shape-${b.shape}" style="--c:${CATEGORIES[b.category]}" data-builder="${kind}" data-text="${esc(b.text)}">${esc(b.text)}</div>`;
  const editValues=t=>{let changed=false;const next=String(t).replace(/\(([^()]*)\)/g,(whole,value)=>{const v=prompt('Edit block value',value);if(v===null)return whole;changed=true;return `(${v})`});return changed?next:String(t)};
  c.innerHTML=`<div class="admin-section-head"><div><h2>🎮 Scratch Level Studio</h2><p>เลือกบล็อกจากคลัง แล้วปรับตัวเลข/ข้อความในบล็อกได้โดยไม่ต้องสร้างคำสั่งซ้ำหลายบล็อก</p></div></div><div class="admin-grid"><label>ชื่อด่าน<input id="stTitle" value="ด่านใหม่จาก Studio"></label><label>ประเภทโจทย์<select id="stType"><option value="sequence">เรียงลำดับบล็อก</option><option value="missing">เติมบล็อกที่หายไป</option><option value="wrong">ค้นหาบล็อกที่ผิด</option><option value="predict">ทายผลลัพธ์</option><option value="challenge">ภารกิจเขียนโปรแกรม</option></select></label><label>เชื่อมบทเรียน<select id="stLesson"><option value="">ไม่กำหนด</option>${ls.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select></label><label>คะแนนครั้งแรก<input id="stFirst" type="number" value="300"></label><label>การตรวจค่าภายในบล็อก<select id="stValueMode"><option value="exact">ตรวจทั้งบล็อกและค่าที่กรอก</option><option value="structure">ตรวจเฉพาะชนิด/ลำดับบล็อก</option></select></label></div><label>คำอธิบายโจทย์<textarea id="stPrompt">ลากบล็อกให้ตัวละครทำงานตามโจทย์</textarea></label><div class="level-builder"><section><h3>คลังบล็อก Scratch</h3><div class="builder-palette">${Object.keys(CATEGORIES).map(cat=>`<h4><span style="color:${CATEGORIES[cat]}">●</span> ${CATEGORY_NAMES[cat]}</h4>${BLOCK_LIBRARY.filter(b=>b.category===cat).map(b=>block(b,'palette')).join('')}`).join('')}</div></section><section><h3>✅ คำตอบที่ถูกต้อง</h3><p>กด ✏️ เพื่อเปลี่ยนค่าของบล็อก เช่น move (10) steps → move (120) steps</p><div id="answerZone" class="builder-dropzone"></div><button id="undoAnswer" class="secondary">↶ ย้อนกลับ</button><button id="clearAnswer" class="danger">ล้างคำตอบ</button><h3>🎭 ตัวลวง</h3><div id="distractorZone" class="builder-dropzone"></div><button id="modeDistractor" class="secondary">โหมดเพิ่มตัวลวง: ปิด</button></section><section><div class="stage-title-row"><h3>▶ ตัวอย่างการทำงาน</h3><span class="demo-badge">Smart Loop Preview</span></div><div id="stStage" class="stage admin-preview-stage stage-scratch-coords"><div class="stage-grid"></div><div id="stTrail" class="motion-trail"></div><div id="stBubble" class="speech-bubble"></div><div id="stSprite" class="sprite">🐱</div></div><div class="value-monitor"><span>X: <b id="stX">0</b></span><span>Y: <b id="stY">0</b></span><span>ทิศ: <b id="stDir">90</b></span></div><p class="small-note">Repeat/Forever จะถูกจำลองหลายรอบแบบจำกัด จึงมองเห็นการเดินชนขอบและเด้งกลับได้ชัดเจน แม้ใช้ move (10) steps</p><div class="actions"><button id="stRun" class="primary">▶ ทดลองคำตอบ</button><button id="stReset" class="secondary">↺ เริ่มใหม่</button></div><div class="card"><h3>ตัวอย่างหน้าผู้เล่น</h3><p id="studentPreviewPrompt"></p><div id="studentPreviewBlocks"></div></div><button id="saveStudio" class="primary" style="width:100%">💾 บันทึกเป็นด่านใหม่</button></section></div>`;
  let distractMode=false;
  const catFor=t=>(BLOCK_LIBRARY.find(b=>b.text===t)||BLOCK_LIBRARY.find(b=>String(t).startsWith(b.text.split('(')[0]))||{}).category||'control';
  const drawZones=()=>{
    $('#answerZone').innerHTML=answer.map((t,i)=>`<div class="code-block-row"><div class="block" style="--c:${CATEGORIES[catFor(t)]}">${esc(t)}</div><button class="block-mini-btn" data-edit-answer="${i}">✏️</button><button class="block-mini-btn danger-mini" data-remove-answer="${i}">×</button></div>`).join('');
    $('#distractorZone').innerHTML=distractors.map((t,i)=>`<div class="code-block-row"><div class="block" style="--c:#777">${esc(t)}</div><button class="block-mini-btn" data-edit-dist="${i}">✏️</button><button class="block-mini-btn danger-mini" data-remove-dist="${i}">×</button></div>`).join('');
    $('#studentPreviewPrompt').textContent=$('#stPrompt').value;$('#studentPreviewBlocks').innerHTML=[...answer,...distractors].sort(()=>Math.random()-.5).map(t=>`<span class="tag">${esc(t)}</span>`).join(' ');
    document.querySelectorAll('[data-edit-answer]').forEach(x=>x.onclick=()=>{const i=+x.dataset.editAnswer;answer[i]=editValues(answer[i]);drawZones()});
    document.querySelectorAll('[data-edit-dist]').forEach(x=>x.onclick=()=>{const i=+x.dataset.editDist;distractors[i]=editValues(distractors[i]);drawZones()});
    document.querySelectorAll('[data-remove-answer]').forEach(x=>x.onclick=()=>{answer.splice(+x.dataset.removeAnswer,1);drawZones()});document.querySelectorAll('[data-remove-dist]').forEach(x=>x.onclick=()=>{distractors.splice(+x.dataset.removeDist,1);drawZones()})
  };
  document.querySelectorAll('[data-builder="palette"]').forEach(b=>b.onclick=()=>{(distractMode?distractors:answer).push(b.dataset.text);drawZones()});
  $('#modeDistractor').onclick=()=>{distractMode=!distractMode;$('#modeDistractor').textContent=`โหมดเพิ่มตัวลวง: ${distractMode?'เปิด':'ปิด'}`};$('#undoAnswer').onclick=()=>{answer.pop();drawZones()};$('#clearAnswer').onclick=()=>{answer=[];drawZones()};$('#stPrompt').oninput=drawZones;
  const st={x:0,y:0,dir:90};const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const nums=t=>(String(t).match(/-?\d+(?:\.\d+)?/g)||[]).map(Number);const first=(t,d=10)=>Number.isFinite(nums(t)[0])?nums(t)[0]:d;
  const drawStage=(trail=true)=>{const sp=$('#stSprite'),xp=50+(Math.max(-240,Math.min(240,st.x))/240)*45,yp=50-(Math.max(-180,Math.min(180,st.y))/180)*40;sp.style.left=xp+'%';sp.style.top=yp+'%';sp.style.transform=`translate(-50%,-50%) rotate(${st.dir-90}deg)`;$('#stX').textContent=Math.round(st.x);$('#stY').textContent=Math.round(st.y);$('#stDir').textContent=Math.round(st.dir);if(trail){const d=document.createElement('i');d.style.left=xp+'%';d.style.top=yp+'%';$('#stTrail').appendChild(d);if($('#stTrail').children.length>80)$('#stTrail').firstElementChild.remove()}};
  const reset=()=>{Object.assign(st,{x:0,y:0,dir:90});$('#stBubble').style.display='none';$('#stTrail').innerHTML='';$('#stStage').classList.remove('edge-hit');drawStage(false)};
  const norm=()=>{while(st.dir>180)st.dir-=360;while(st.dir<=-180)st.dir+=360};
  const bounce=()=>{let hx=false,hy=false;if(st.x>220){st.x=220;hx=true}else if(st.x<-220){st.x=-220;hx=true}if(st.y>155){st.y=155;hy=true}else if(st.y<-155){st.y=-155;hy=true}if(hx)st.dir=-st.dir;if(hy)st.dir=180-st.dir;norm();if(hx||hy){$('#stStage').classList.add('edge-hit');setTimeout(()=>$('#stStage')?.classList.remove('edge-hit'),180)}};
  const exec=async(t,delay=150)=>{const n=first(t);if(t.startsWith('move')){const r=st.dir*Math.PI/180;st.x+=Math.sin(r)*n;st.y+=Math.cos(r)*n}else if(t.startsWith('turn right')){st.dir+=n;norm()}else if(t.startsWith('turn left')){st.dir-=n;norm()}else if(t.startsWith('point in direction')){st.dir=n;norm()}else if(t.startsWith('change x'))st.x+=n;else if(t.startsWith('change y'))st.y+=n;else if(t.startsWith('set x'))st.x=n;else if(t.startsWith('set y'))st.y=n;else if(t.startsWith('go to x')){const v=nums(t);st.x=v[0]||0;st.y=v[1]||0}else if(t==='if on edge, bounce')bounce();else if(t.startsWith('say')){const b=$('#stBubble');b.textContent=(t.match(/\((.*?)\)/)||['','Hello!'])[1];b.style.display='block'}drawStage();await sleep(delay)};
  const body=async(list,cycles)=>{for(let c=0;c<cycles;c++)for(const t of list){if(t.startsWith('when ')||t==='forever'||t.startsWith('repeat ('))continue;await exec(t,cycles>1?55:180)}};
  const run=async()=>{reset();const ex=answer.filter(t=>!t.startsWith('when ')),fi=ex.indexOf('forever'),ri=ex.findIndex(t=>t.startsWith('repeat ('));if(fi>=0)return body(ex.slice(fi+1),60);if(ri>=0)return body(ex.slice(ri+1),Math.max(1,Math.min(30,first(ex[ri],10))));return body(ex,1)};
  $('#stRun').onclick=run;$('#stReset').onclick=reset;
  $('#saveStudio').onclick=()=>{if(!answer.length)return alert('กรุณาเลือกบล็อกคำตอบอย่างน้อย 1 บล็อก');const levels=get(K.levels,LEVELS),id='V'+Date.now(),order=Math.max(0,...levels.map(x=>+x.order||0))+1;levels.push({id,order,title:$('#stTitle').value.trim()||'ด่านใหม่',type:$('#stType').value,prompt:$('#stPrompt').value,lessonIds:$('#stLesson').value?[$('#stLesson').value]:[],previousLevelId:levels.sort((a,b)=>a.order-b.order).at(-1)?.id||'',firstScore:+$('#stFirst').value||300,repeatScore:100,answer:[...answer],distractors:[...distractors],valueMode:$('#stValueMode').value,published:true,createdWithStudio:true});set(K.levels,levels);syncContent();alert('บันทึกด่านแล้ว');studioTab(c)};
  drawZones();reset();
}

const DEFAULT_CONTACTS_ADMIN={title:'ติดต่อผู้ดูแลระบบ',description:'พบปัญหาหรือต้องการสอบถาม สามารถติดต่อผ่านช่องทางด้านล่าง',channels:[{id:'facebook',label:'Facebook แอดมิน',icon:'📘',url:'https://www.facebook.com/kriang.sak.47',enabled:true}]};
const DEFAULT_AUDIO_ADMIN={enabled:true,music:{enabled:true,url:'',volume:.28,loop:true},effects:{enabled:true,volume:.72,clickUrl:'',successUrl:'',errorUrl:'',rewardUrl:''},ducking:true};
async function saveAdminSystem(key,doc,data){set(key,data);try{if(cloud.enabled)await cloud.saveSystemDoc(doc,data);alert('บันทึกและส่งไปหน้าเกมแล้ว')}catch(e){console.error(e);alert('บันทึกในเครื่องแล้ว แต่ส่งขึ้น Firebase ไม่สำเร็จ: '+(e.message||e))}}
async function announcementsTab(c){let items=get(K.announcements,[]);try{if(cloud.enabled){const remote=await cloud.listAnnouncements();if(remote.length||!items.length){items=remote;set(K.announcements,items)}}}catch(e){console.error(e)}
 const render=()=>{c.innerHTML=`<div class="editor-card"><h3>📢 สร้างประกาศ</h3><div class="admin-grid"><label>หัวข้อ<input id="anTitle" placeholder="ประกาศสำคัญ"></label><label>ลำดับความสำคัญ<input id="anPriority" type="number" value="1"></label><label>เริ่มแสดง<input id="anStart" type="datetime-local"></label><label>สิ้นสุด<input id="anEnd" type="datetime-local"></label></div><label>ข้อความ<textarea id="anMessage" placeholder="ข้อความที่ต้องการประกาศ"></textarea></label><label><input id="anSpeak" type="checkbox"> อ่านประกาศด้วยเสียง</label><label><input id="anEnabled" type="checkbox" checked> เปิดใช้งาน</label><div class="actions"><button id="anSave" class="primary">💾 เพิ่มประกาศ</button></div></div><div id="anList">${items.map(a=>`<div class="editor-card"><h3>${esc(a.title||'ประกาศ')}</h3><p>${esc(a.message||'')}</p><small>${a.enabled===false?'⛔ ปิด':'✅ เปิด'} · Priority ${Number(a.priority||0)}</small><div class="actions"><button class="danger" data-del-an="${esc(a.id)}">ลบ</button></div></div>`).join('')||'<div class="editor-card">ยังไม่มีประกาศ</div>'}</div>`;
 $('#anSave').onclick=async()=>{const a={id:'A'+Date.now(),title:$('#anTitle').value.trim(),message:$('#anMessage').value.trim(),priority:+$('#anPriority').value||0,startAt:$('#anStart').value?new Date($('#anStart').value).toISOString():'',endAt:$('#anEnd').value?new Date($('#anEnd').value).toISOString():'',speak:$('#anSpeak').checked,enabled:$('#anEnabled').checked};if(!a.message)return alert('กรุณาใส่ข้อความประกาศ');items=[a,...items];set(K.announcements,items);try{if(cloud.enabled)await cloud.saveAnnouncement(a);alert('เผยแพร่ประกาศแล้ว')}catch(e){alert('บันทึกในเครื่องแล้ว แต่ Firebase ไม่สำเร็จ: '+(e.message||e))}render()};
 document.querySelectorAll('[data-del-an]').forEach(b=>b.onclick=async()=>{const id=b.dataset.delAn;items=items.filter(x=>x.id!==id);set(K.announcements,items);try{if(cloud.enabled)await cloud.deleteAnnouncement(id)}catch(e){console.error(e)}render()})};render()}
function systemTab(c){const m=get(K.maintenance,{enabled:false,title:'กำลังปรับปรุงระบบ',message:'กรุณากลับมาใหม่ภายหลัง',image:'🛠️',reopenAt:'',speak:false});c.innerHTML=`<div class="editor-card"><h3>🛠️ ปิดระบบเพื่อปรับปรุง</h3><label><input id="mtEnabled" type="checkbox" ${m.enabled?'checked':''}> เปิดโหมดปิดปรับปรุง</label><div class="admin-grid"><label>หัวข้อ<input id="mtTitle" value="${esc(m.title||'')}"></label><label>ไอคอน/Emoji<input id="mtImage" value="${esc(m.image||'🛠️')}"></label><label>คาดว่าจะเปิดอีกครั้ง<input id="mtReopen" type="datetime-local" value="${m.reopenAt?esc(String(m.reopenAt).slice(0,16)):''}"></label></div><label>ข้อความ<textarea id="mtMessage">${esc(m.message||'')}</textarea></label><label><input id="mtSpeak" type="checkbox" ${m.speak?'checked':''}> อ่านข้อความด้วยเสียง</label><div class="actions"><button id="mtSave" class="primary">💾 บันทึกสถานะระบบ</button></div><p>เมื่อเปิดใช้งาน หน้าเกมของนักเรียนที่ออนไลน์จะได้รับสถานะผ่าน Firebase แบบเรียลไทม์</p></div>`;$('#mtSave').onclick=()=>saveAdminSystem(K.maintenance,'maintenance',{enabled:$('#mtEnabled').checked,title:$('#mtTitle').value.trim(),message:$('#mtMessage').value.trim(),image:$('#mtImage').value.trim()||'🛠️',reopenAt:$('#mtReopen').value?new Date($('#mtReopen').value).toISOString():'',speak:$('#mtSpeak').checked})}
function contactsTab(c){const x=get(K.contacts,DEFAULT_CONTACTS_ADMIN),channels=Array.isArray(x.channels)?x.channels:DEFAULT_CONTACTS_ADMIN.channels;c.innerHTML=`<div class="editor-card"><h3>💬 ช่องทางติดต่อ</h3><label>หัวข้อ<input id="ctTitle" value="${esc(x.title||'')}"></label><label>คำอธิบาย<textarea id="ctDesc">${esc(x.description||'')}</textarea></label><div id="ctRows">${channels.map((ch,i)=>`<div class="admin-grid editor-card"><label>ไอคอน<input data-ct-icon="${i}" value="${esc(ch.icon||'🔗')}"></label><label>ชื่อช่องทาง<input data-ct-label="${i}" value="${esc(ch.label||'')}"></label><label>URL<input type="url" data-ct-url="${i}" value="${esc(ch.url||'')}"></label><label><input type="checkbox" data-ct-on="${i}" ${ch.enabled!==false?'checked':''}> เปิดใช้งาน</label></div>`).join('')}</div><div class="actions"><button id="ctAdd" class="secondary">+ เพิ่มช่องทาง</button><button id="ctSave" class="primary">💾 บันทึกช่องทางติดต่อ</button></div></div>`;$('#ctAdd').onclick=()=>{channels.push({id:'link'+Date.now(),icon:'🔗',label:'ช่องทางใหม่',url:'',enabled:true});set(K.contacts,{title:$('#ctTitle').value,description:$('#ctDesc').value,channels});contactsTab(c)};$('#ctSave').onclick=()=>{const out=channels.map((ch,i)=>({...ch,icon:document.querySelector(`[data-ct-icon="${i}"]`)?.value||'🔗',label:document.querySelector(`[data-ct-label="${i}"]`)?.value||'',url:document.querySelector(`[data-ct-url="${i}"]`)?.value.trim()||'',enabled:!!document.querySelector(`[data-ct-on="${i}"]`)?.checked}));saveAdminSystem(K.contacts,'contacts',{title:$('#ctTitle').value.trim(),description:$('#ctDesc').value.trim(),channels:out})}}
function audioTab(c){const a={...DEFAULT_AUDIO_ADMIN,...get(K.audio,{}),music:{...DEFAULT_AUDIO_ADMIN.music,...(get(K.audio,{})?.music||{})},effects:{...DEFAULT_AUDIO_ADMIN.effects,...(get(K.audio,{})?.effects||{})}};c.innerHTML=`<div class="editor-card"><h3>🎵 ระบบเสียง</h3><label><input id="auEnabled" type="checkbox" ${a.enabled?'checked':''}> เปิดระบบเสียงทั้งหมด</label><h4>เพลงพื้นหลัง</h4><label><input id="auMusicOn" type="checkbox" ${a.music.enabled?'checked':''}> เปิดเพลงพื้นหลัง</label><label>URL เพลง<input id="auMusicUrl" type="url" value="${esc(a.music.url||'')}" placeholder="https://...mp3"></label><label>ความดังเพลง <output id="auMusicOut">${Math.round(a.music.volume*100)}%</output><input id="auMusicVol" type="range" min="0" max="1" step="0.01" value="${a.music.volume}"></label><label><input id="auLoop" type="checkbox" ${a.music.loop!==false?'checked':''}> เล่นวนซ้ำ</label><h4>เสียงกด / เอฟเฟกต์</h4><label><input id="auFxOn" type="checkbox" ${a.effects.enabled?'checked':''}> เปิดเสียงเอฟเฟกต์</label><label>ความดัง <output id="auFxOut">${Math.round(a.effects.volume*100)}%</output><input id="auFxVol" type="range" min="0" max="1" step="0.01" value="${a.effects.volume}"></label>${[['clickUrl','เสียงกด'],['successUrl','เสียงสำเร็จ'],['errorUrl','เสียงผิด'],['rewardUrl','เสียงรางวัล']].map(([k,n])=>`<label>${n} URL<input id="${k}" type="url" value="${esc(a.effects[k]||'')}" placeholder="เว้นว่างเพื่อใช้เสียงในระบบ"></label>`).join('')}<div class="actions"><button id="auTest" class="secondary">🔊 ทดสอบเสียงกด</button><button id="auSave" class="primary">💾 บันทึกระบบเสียง</button></div><small>หมายเหตุ: เบราว์เซอร์จะเริ่มเพลงหลังผู้ใช้แตะ/คลิกหน้าเว็บครั้งแรกตามนโยบาย Autoplay</small></div>`;$('#auMusicVol').oninput=()=>$('#auMusicOut').textContent=Math.round(+$('#auMusicVol').value*100)+'%';$('#auFxVol').oninput=()=>$('#auFxOut').textContent=Math.round(+$('#auFxVol').value*100)+'%';$('#auTest').onclick=()=>{window.SARAudio?.apply?.({enabled:true,effects:{enabled:true,volume:+$('#auFxVol').value,clickUrl:$('#clickUrl').value.trim()}});window.SARAudio?.play?.('click')};$('#auSave').onclick=()=>saveAdminSystem(K.audio,'audioSettings',{enabled:$('#auEnabled').checked,music:{enabled:$('#auMusicOn').checked,url:$('#auMusicUrl').value.trim(),volume:+$('#auMusicVol').value,loop:$('#auLoop').checked},effects:{enabled:$('#auFxOn').checked,volume:+$('#auFxVol').value,clickUrl:$('#clickUrl').value.trim(),successUrl:$('#successUrl').value.trim(),errorUrl:$('#errorUrl').value.trim(),rewardUrl:$('#rewardUrl').value.trim()},ducking:true})}

function themeTab(c){const s={...DEFAULT_THEME,...get(K.settings,{})};c.innerHTML=`<div class="admin-grid"><div><h3>ค่าหน้าตาระบบ</h3><label>ชุดธีม<select id="themePreset"><option value="pastel">Pastel Classroom</option><option value="ocean">Ocean Blue</option><option value="forest">Forest Green</option><option value="sunset">Sunset Orange</option><option value="dark">Dark Galaxy</option></select></label><label>สีหลัก<input id="primary" type="color" value="${s.primary}"></label><label>สีเน้น<input id="accent" type="color" value="${s.accent}"></label>${[['panelOpacity','ความทึบแผง',.25,1,.01],['cardOpacity','ความทึบการ์ด',.35,1,.01],['blur','ความเบลอพื้นหลัง',0,30,1],['radius','ความโค้งมน',8,48,1],['scale','ขนาด UI',.85,1.25,.05]].map(([id,n,min,max,step])=>`<div class="range-row"><b>${n}</b><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${s[id]}"><output id="${id}Out">${s[id]}</output></div>`).join('')}<div class="actions" style="justify-content:flex-start"><button id="saveTheme" class="primary">บันทึกและใช้กับผู้เล่น</button><button id="resetTheme" class="secondary">ค่าเริ่มต้น</button></div></div><div><h3>ตัวอย่างทันที</h3><div id="preview" class="theme-preview"><div class="sample-panel"><h2>Scratch AR Adventure</h2><div class="card"><b>ตัวอย่างการ์ดบทเรียน</b><p>ปรับความโปร่งใส สี ความเบลอ และขนาดได้</p><button class="primary">ปุ่มหลัก</button></div></div></div></div></div>`;$('#themePreset').value=s.theme;const ids=['panelOpacity','cardOpacity','blur','radius','scale'];const presets={pastel:{primary:'#6c5ce7',accent:'#ffb703'},ocean:{primary:'#0984e3',accent:'#00cec9'},forest:{primary:'#00a86b',accent:'#f9ca24'},sunset:{primary:'#e17055',accent:'#fdcb6e'},dark:{primary:'#6c5ce7',accent:'#00cec9'}};function preview(){const pv=$('#preview'),panel=pv.querySelector('.sample-panel'),card=pv.querySelector('.card'),pri=$('#primary').value;panel.style.background=`rgba(255,255,255,${$('#panelOpacity').value})`;panel.style.backdropFilter=`blur(${$('#blur').value}px)`;panel.style.borderRadius=`${$('#radius').value}px`;card.style.background=`rgba(255,255,255,${$('#cardOpacity').value})`;pv.style.fontSize=`${$('#scale').value}em`;pv.querySelector('.primary').style.background=pri;ids.forEach(id=>$('#'+id+'Out').textContent=$('#'+id).value)};['primary','accent',...ids].forEach(id=>$('#'+id).oninput=preview);$('#themePreset').onchange=()=>{const p=presets[$('#themePreset').value];$('#primary').value=p.primary;$('#accent').value=p.accent;if($('#themePreset').value==='dark'){$('#panelOpacity').value=.60;$('#cardOpacity').value=.78}else{$('#panelOpacity').value=.76;$('#cardOpacity').value=.90}preview()};$('#saveTheme').onclick=()=>{set(K.settings,{theme:$('#themePreset').value,primary:$('#primary').value,accent:$('#accent').value,panelOpacity:Number($('#panelOpacity').value),cardOpacity:Number($('#cardOpacity').value),blur:Number($('#blur').value),radius:Number($('#radius').value),scale:Number($('#scale').value)});syncSettings();alert('บันทึก UI แล้ว หน้าเกมทุกเครื่องจะใช้ค่าเมื่อรีเฟรช')};$('#resetTheme').onclick=()=>{set(K.settings,DEFAULT_THEME);syncSettings();themeTab(c)};preview()}
function logsTab(c){const ev=get(K.events,[]).slice().reverse();c.innerHTML=`${ev.map(e=>`<div class="editor-card"><b>${esc(e.type)}</b> <small>${esc(e.at)}</small><pre>${esc(JSON.stringify(e.data,null,2))}</pre></div>`).join('')||'<p>ยังไม่มีข้อมูล</p>'}`}
function backupTab(c){c.innerHTML=`<div class="editor-card"><h3>สำรองข้อมูลทั้งหมด</h3><button id="exp" class="primary">ดาวน์โหลด JSON</button></div><div class="editor-card"><h3>นำเข้าข้อมูล</h3><label>เลือกไฟล์ JSON<input id="imp" type="file" accept="application/json"></label></div><div class="editor-card"><h3>คืนค่าเริ่มต้น</h3><button id="reset" class="danger">คืนค่าบทเรียนและด่านเริ่มต้น</button></div>`;$('#exp').onclick=()=>{const data={users:get(K.users,[]),lessons:get(K.lessons,[]),levels:get(K.levels,[]),settings:get(K.settings,DEFAULT_THEME),events:get(K.events,[]),exportedAt:new Date().toISOString()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='scratch-ar-backup.json';a.click()};$('#imp').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());for(const [n,k] of Object.entries(K))if(d[n])set(k,d[n]);alert('นำเข้าแล้ว')}catch{alert('ไฟล์ไม่ถูกต้อง')}};$('#reset').onclick=()=>{if(confirm('ยืนยันคืนค่าเริ่มต้น?')){set(K.lessons,LESSONS);set(K.levels,LEVELS);syncContent();alert('เรียบร้อย')}}}
(async()=>{await cloud.init();if(auth){await hydrateCloud();dashboard()}else login();if(!cloud.enabled)console.warn('Admin กำลังใช้โหมด localStorage เพราะยังไม่ได้ตั้งค่า Firebase')})();


function gameBuilderTab(c){
 const ls=get(K.lessons,LESSONS), all=get(K.levels,LEVELS);
 c.innerHTML=`<div class="admin-section-head"><div><h2>🕹️ Game Creator Studio</h2><p>สร้างเกมเสริมแล้วเพิ่มลงแผนที่ด่านได้ทันที</p></div></div>
 <div class="admin-grid"><label>ชื่อเกม<input id="gbTitle" value="เกมใหม่"></label><label>ประเภทเกม<select id="gbType"><option value="quiz">❓ เกมตอบคำถาม</option><option value="matching">🧠 เกมจับคู่</option><option value="sorting">🗂️ เกมแยกประเภท</option></select></label><label>บทเรียนที่ต้องเรียน<select id="gbLesson"><option value="">ไม่กำหนด</option>${ls.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><label>คะแนนครั้งแรก<input id="gbScore" type="number" value="200"></label></div>
 <label>โจทย์ / คำสั่ง<textarea id="gbPrompt">เลือกคำตอบที่ถูกต้อง</textarea></label><div id="gbFields"></div><div class="editor-card"><h3>👀 Preview</h3><div id="gbPreview"></div></div><button id="gbSave" class="primary">💾 เพิ่มเกมลงแผนที่ด่าน</button>`;
 const fields=$('#gbFields'), preview=$('#gbPreview');
 function draw(){const t=$('#gbType').value;if(t==='quiz')fields.innerHTML=`<div class="editor-card"><h3>คำตอบ</h3><label>ตัวเลือก (1 บรรทัดต่อ 1 ตัวเลือก)<textarea id="gbOptions">Motion\nLooks\nEvents\nControl</textarea></label><label>คำตอบที่ถูกต้อง<input id="gbCorrect" value="Motion"></label></div>`;if(t==='matching')fields.innerHTML=`<div class="editor-card"><h3>คู่คำตอบ</h3><p>รูปแบบ: ด้านซ้าย | ด้านขวา</p><textarea id="gbPairs">move (10) steps | Move the sprite forward\nsay (Hello!) | Show a speech bubble\nwhen green flag clicked | Start the program</textarea></div>`;if(t==='sorting')fields.innerHTML=`<div class="editor-card"><h3>หมวดและรายการ</h3><label>หมวด (คั่นด้วย |)<input id="gbCats" value="Motion | Looks | Events"></label><p>รูปแบบ: รายการ | หมวดที่ถูกต้อง</p><textarea id="gbItems">move (10) steps | Motion\nsay (Hello!) | Looks\nwhen green flag clicked | Events</textarea></div>`;renderPreview()}
 function lines(id){return ($('#'+id)?.value||'').split('\n').map(x=>x.trim()).filter(Boolean)}
 function renderPreview(){const t=$('#gbType').value,p=esc($('#gbPrompt').value||'');if(t==='quiz')preview.innerHTML=`<h3>${p}</h3>${lines('gbOptions').map(x=>`<button class="secondary" style="margin:5px">${esc(x)}</button>`).join('')}`;if(t==='matching')preview.innerHTML=`<h3>${p}</h3><p>แตะรายการซ้ายและขวาเพื่อจับคู่</p>${lines('gbPairs').map(x=>`<span class="tag">${esc(x)}</span> `).join('')}`;if(t==='sorting')preview.innerHTML=`<h3>${p}</h3><p>${($('#gbCats')?.value||'').split('|').map(x=>`<span class="tag">📦 ${esc(x.trim())}</span>`).join(' ')}</p>${lines('gbItems').map(x=>`<span class="tag">${esc(x.split('|')[0].trim())}</span> `).join('')}`}
 $('#gbType').onchange=draw;$('#gbPrompt').oninput=renderPreview;fields.addEventListener('input',renderPreview);draw();
 $('#gbSave').onclick=()=>{const t=$('#gbType').value,id='G'+Date.now(),order=Math.max(0,...all.map(x=>+x.order||0))+1,obj={id,order,title:$('#gbTitle').value.trim()||'เกมใหม่',gameType:t,prompt:$('#gbPrompt').value.trim(),lessonIds:$('#gbLesson').value?[$('#gbLesson').value]:[],previousLevelId:null,firstScore:+$('#gbScore').value||200,repeatScore:50,published:true};if(t==='quiz'){obj.options=lines('gbOptions');obj.correct=$('#gbCorrect').value.trim()}if(t==='matching')obj.pairs=lines('gbPairs').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x.length>1);if(t==='sorting'){obj.categories=($('#gbCats').value||'').split('|').map(x=>x.trim()).filter(Boolean);obj.items=lines('gbItems').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x.length>1)}all.push(obj);set(K.levels,all);syncContent();alert('เพิ่มเกมลงแผนที่ด่านแล้ว');gameBuilderTab(c)}
}
